  const sameShape = diary.filter(d => d.shape === look.shape);

  // If a trait (color/smell/shape) has ONLY ever caused harm, avoid it entirely
  const isTraitDangerous = (arr) => arr.length > 0 && arr.every(b => b.harmed);
  if (isTraitDangerous(sameColor)) return 'leave';

  // If a trait has fed us more than harmed, trust it. If novel but safe traits exist, taste cautiously.
