    return r.harmed ? 'leave' : 'eat';
  }

  // Unknown species: Use trait inference
  let dangerScore = 0;
  let benefitScore = 0;

  if (isTraitBeneficial(sameColor)) benefitScore++;
  else if (isTraitDangerous(sameColor)) dangerScore++;

  if (isTraitBeneficial(sameSmell)) benefitScore++;
  else if (isTraitDangerous(sameSmell)) dangerScore++;

  if (isTraitBeneficial(sameShape)) benefitScore++;
