function recall(key, diary) {
  let poisoned = false, safe = false, eaten = false;
  // Process newest first for recent trait shifts
  for (let i = diary.length - 1; i >= 0; i--) {
    const b = diary[i];
    if (b.key !== key) continue;
    if (b.harmed) { poisoned = true; break; } // Poison overrides past safety
    if (!safe && !eaten) { safe = true; } // First non-harmful bite suggests safety
    eaten = true;
  }
  return { poisoned, safe, eaten, unknown: !eaten };
}

